-- Sales leads, follow-ups and their status masters for Microsoft SQL Server.
SET XACT_ABORT ON; BEGIN TRANSACTION;
CREATE TABLE [dbo].[LeadStatuses] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_LeadStatuses] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [Code] NVARCHAR(40) NOT NULL, [Name] NVARCHAR(120) NOT NULL, [DisplayOrder] INT NOT NULL, [Color] NVARCHAR(20) NULL, [IsClosed] BIT NOT NULL, [IsActive] BIT NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, [UpdatedAtUtc] DATETIMEOFFSET NOT NULL, CONSTRAINT [FK_LeadStatuses_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]));
CREATE UNIQUE INDEX [UX_LeadStatuses_Id] ON [dbo].[LeadStatuses]([Id]); CREATE UNIQUE INDEX [UX_LeadStatuses_Tenant_Code] ON [dbo].[LeadStatuses]([TenantId],[Code]);
CREATE TABLE [dbo].[FollowUpStatuses] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_FollowUpStatuses] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [Code] NVARCHAR(40) NOT NULL, [Name] NVARCHAR(120) NOT NULL, [DisplayOrder] INT NOT NULL, [Color] NVARCHAR(20) NULL, [IsCompleted] BIT NOT NULL, [IsActive] BIT NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, [UpdatedAtUtc] DATETIMEOFFSET NOT NULL, CONSTRAINT [FK_FollowUpStatuses_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]));
CREATE UNIQUE INDEX [UX_FollowUpStatuses_Id] ON [dbo].[FollowUpStatuses]([Id]); CREATE UNIQUE INDEX [UX_FollowUpStatuses_Tenant_Code] ON [dbo].[FollowUpStatuses]([TenantId],[Code]);
CREATE TABLE [dbo].[SalesLeads] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_SalesLeads] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [LeadNumber] NVARCHAR(40) NOT NULL, [CustomerName] NVARCHAR(160) NOT NULL, [Phone] NVARCHAR(40) NOT NULL, [Email] NVARCHAR(254) NULL, [Source] NVARCHAR(100) NULL, [MoveType] NVARCHAR(80) NOT NULL, [Origin] NVARCHAR(300) NOT NULL, [Destination] NVARCHAR(300) NOT NULL, [ExpectedMoveDate] DATE NULL, [StatusId] UNIQUEIDENTIFIER NOT NULL, [AssignedEmployeeId] UNIQUEIDENTIFIER NULL, [Notes] NVARCHAR(2000) NULL, [IsActive] BIT NOT NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, [UpdatedAtUtc] DATETIMEOFFSET NOT NULL, CONSTRAINT [FK_SalesLeads_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]), CONSTRAINT [FK_SalesLeads_LeadStatuses] FOREIGN KEY ([StatusId]) REFERENCES [dbo].[LeadStatuses]([Id]), CONSTRAINT [FK_SalesLeads_Employees] FOREIGN KEY ([AssignedEmployeeId]) REFERENCES [dbo].[Employees]([Id]));
CREATE UNIQUE INDEX [UX_SalesLeads_Id] ON [dbo].[SalesLeads]([Id]); CREATE UNIQUE INDEX [UX_SalesLeads_Tenant_Number] ON [dbo].[SalesLeads]([TenantId],[LeadNumber]); CREATE INDEX [IX_SalesLeads_Tenant_Latest] ON [dbo].[SalesLeads]([TenantId],[SerialNo] DESC);
CREATE TABLE [dbo].[LeadFollowUps] ([SerialNo] INT IDENTITY(1,1) NOT NULL CONSTRAINT [PK_LeadFollowUps] PRIMARY KEY, [Id] UNIQUEIDENTIFIER NOT NULL, [TenantId] UNIQUEIDENTIFIER NOT NULL, [SalesLeadId] UNIQUEIDENTIFIER NOT NULL, [ScheduledAtUtc] DATETIMEOFFSET NOT NULL, [StatusId] UNIQUEIDENTIFIER NOT NULL, [Notes] NVARCHAR(2000) NOT NULL, [NextFollowUpAtUtc] DATETIMEOFFSET NULL, [CreatedAtUtc] DATETIMEOFFSET NOT NULL, [UpdatedAtUtc] DATETIMEOFFSET NOT NULL, CONSTRAINT [FK_LeadFollowUps_Tenants] FOREIGN KEY ([TenantId]) REFERENCES [dbo].[Tenants]([Id]), CONSTRAINT [FK_LeadFollowUps_SalesLeads] FOREIGN KEY ([SalesLeadId]) REFERENCES [dbo].[SalesLeads]([Id]), CONSTRAINT [FK_LeadFollowUps_Statuses] FOREIGN KEY ([StatusId]) REFERENCES [dbo].[FollowUpStatuses]([Id]));
CREATE UNIQUE INDEX [UX_LeadFollowUps_Id] ON [dbo].[LeadFollowUps]([Id]); CREATE INDEX [IX_LeadFollowUps_Lead_Latest] ON [dbo].[LeadFollowUps]([SalesLeadId],[SerialNo] DESC);
COMMIT TRANSACTION;
